 const bank=data.activities.filter((a:any)=>(!filter||`${a.title} ${a.objective}`.toLowerCase().includes(filter.toLowerCase()))&&(!subject||a.subject===subject)&&(!studentFilter||a.studentId===studentFilter||a.suggestedStudentIds?.includes(studentFilter)||(!a.studentId&&!a.suggestedStudentIds?.length))&&(!supportFilter||activitySupportMode(a.supportMode)===supportFilter));
 const resources=data.resources.filter((r:any)=>(!pdfWorkFilter||(()=>{const pdf=pdfFileForResource(r,data.files||[]);return Boolean(pdf)&&Boolean(pdf?._pdfWorkedAt)===(pdfWorkFilter==='done')})())&&(!filter||`${r.title} ${r.objective}`.toLowerCase().includes(filter.toLowerCase()))&&(!subject||r.subject===subject)&&(!studentFilter||r.studentId===studentFilter||r.suggestedStudentIds?.includes(studentFilter)||(!r.studentId&&!r.suggestedStudentIds?.length))&&(!supportFilter||activitySupportMode(r.supportMode)===supportFilter)).sort((a:any,b:any)=>Number(Boolean(pdfFileForResource(b,data.files||[])))-Number(Boolean(pdfFileForResource(a,data.files||[])))||String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')));
 const visibleBank=tab==='Banco de actividades'?bank:resources;
 const worksheetActivity=(resource:any)=>worksheetForResource(resource.id,data.activities);
