 const pupil=data.students.find((s:any)=>s.id===item.studentId||s.id===item.id),allSubjects=data.subjects||[];
 const reviewActivity=data.activities.find((activity:any)=>activity.id===item.activityId||activity.id===data.assignments.find((assignment:any)=>assignment.id===item.assignmentId)?.activityId),reviewResource=data.resources.find((resource:any)=>resource.id===item.resourceId);
 const existingSkill=type==='skill'&&data.skills.some((s:any)=>s.id===item.id);
 const modalFiles=[...(data.files||[]),...(uploadedFile?[uploadedFile]:[])],linkedResource=f.resourceId?data.resources.find((resource:any)=>resource.id===f.resourceId):undefined,linkedPdf=linkedResource?pdfFileForResource(linkedResource,modalFiles):undefined,resourcePdf=type==='resource'?pdfFileForResource(f,modalFiles):undefined,resourceWorksheet=type==='resource'?worksheetForResource(f.id,data.activities):undefined;

