 const scopedStudent=f.studentId||(f.suggestedStudentIds?.length===1?f.suggestedStudentIds[0]:'');
 const subjectNames=scopedStudent?examSubjectsForStudent(allSubjects.map((s:any)=>s.name),scopedStudent):allSubjects.map((s:any)=>s.name);
